package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaPlDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_seeing_first_fruit" to DuaText("Widzenie pierwszych owoców", "O Allahu, pobłogosław nas w naszych owocach, pobłogosław nas w naszym mieście i pobłogosław nas w naszym sa' i naszym błocie (miarach).", "Po zobaczeniu pierwszych owoców sezonu.", "Dua o błogosławieństwo w zaopatrzeniu i we własnym mieście."),
        "dua_good_news" to DuaText("Po przyjemnych wiadomościach", "Wszelka chwała należy się Allahowi, dzięki którego łasce dopełniają się dobre rzeczy.", "Po otrzymaniu dobrych wieści (i wykonaniu pokłonu wdzięczności).", "Prorok ﷺ powiedział to, widząc coś, co mu się podobało."),
        "dua_looking_mirror" to DuaText("Patrząc w lustro", "O Allahu, tak jak uczyniłeś mój wygląd dobrym, uczyń także mój charakter dobrym.", "Kiedy patrzysz w lustro.", "Prorok ﷺ uczynił to dua (jest to ustalone nawet bez wzmianki o lustrze)."),
        "dua_rabbana_taqabbal" to DuaText("Akceptacja czynów", "Panie nasz, przyjmij to od nas; zaprawdę, Ty jesteś Wszystkosłyszący, Wszechwiedzący. I przyjmij naszą skruchę; zaiste, Ty jesteś Przyjmujący pokutę, Miłosierny.", "Pytanie zadane przez Ibrahima i Isma'ila (AS) podczas budowy Ka'by.", "Dua o przyjęcie po każdym dobrym uczynku."),
        "dua_muawwidhat" to DuaText("Trzy Quls (Mu'awwidhat)", "(Sura al-Ikhlas) Powiedz: On jest Allahem, Jedynym. Allah, Samowystarczalny. On nie rodzi, ani się nie rodzi. I nie ma nikogo, kto mógłby się z Nim równać.\n\n(Sura al-Falaq) Powiedz: Szukam schronienia u Pana jutrzenki, przed złem tego, co stworzył, przed złem ciemności, gdy zapada, przed złem tych, którzy dmuchają na węzły, i przed złem zazdrości, gdy zazdrości.\n\n(Sura an-Nas) Powiedz: Szukam schronienia u Pana ludzkości, Króla ludzkości, Boga ludzkości, przed złem wycofującego się szeptacza, który szepcze do serc ludzkości, spośród dżinów i ludzkości.", "Trzy sury trzy razy rano i wieczorem oraz przed snem dmuchnij w dłonie i przetrzyj nimi ciało.", "Trzykrotne recytowanie ich rano i wieczorem wystarczy na wszystko."),
        "dua_sabr" to DuaText("Za cierpliwość i wytrwałość", "Panie nasz, wylej na nas cierpliwość, utwierdz nasze stopy i pomóż nam w walce z niewiernym ludem.", "W chwilach trudności i konfrontacji.", "Dua armii Taluta."),
        "dua_rabbana_innana_amanna" to DuaText("Przebaczenie i ochrona przed ogniem", "Uwierzyliśmy, Panie nasz, więc przebacz nam nasze grzechy i chroń nas od kary Ognia.", "Koraniczny duet.", "Dua wymieniona wśród cech bogobojnych."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("Wskazówki w naszej sprawie (Ashab al-Kahf)", "Panie nasz, udziel nam miłosierdzia od siebie i przygotuj nam właściwe przewodnictwo w naszej sprawie.", "Duet Ludu Jaskini.", "Pomoc w podejmowaniu decyzji i trudnych sytuacjach."),
        "dua_musa_faqir" to DuaText("Dua Musa (AS) dla zaopatrzenia", "Mój Panie, naprawdę potrzebuję wszelkiego dobra, które mi zesłasz.", "Poszukiwanie zaopatrzenia i dobra — dua Musa (AS) w Madyan.", "Po tym duecie Allah obdarzył Musę (AS) domem, pracą i żoną."),
        "dua_ayyub" to DuaText("Dua z Ayyub (AS) w chorobie", "(Mój Panie) dotknęła mnie krzywda, a Ty jesteś Najbardziej Miłosierny z miłosiernych.", "W chorobie i cierpieniu.", "Allah usunął cierpienie Ayyuba (AS)."),
        "dua_husn_khatimah" to DuaText("Umrzyj jako muzułmanin (Yusuf AS)", "Stwórco niebios i ziemi, jesteś moim Obrońcą na tym świecie i w życiu ostatecznym. Spraw, żebym umarł jako muzułmanin i przyłącz się do sprawiedliwych.", "Duet na dobre zakończenie.", "Dua Proroka Yusufa (AS)."),
        "dua_shaitan_hamazat" to DuaText("Schronienie przed szeptami diabła", "Panie mój, szukam schronienia u Ciebie przed podszeptami diabłów i u Ciebie, Panie mój, szukam schronienia, aby się do mnie nie zbliżyli.", "Schronienie się przed szatańskimi szeptami.", "Koraniczny duet szukania schronienia."),
        "dua_bad_character" to DuaText("Schronienie przed złym charakterem", "O Allahu, szukam u Ciebie schronienia przed złym charakterem, złymi uczynkami i złymi pragnieniami.", "Schronienie się przed złym charakterem, czynami i pragnieniami.", "Dua schronienia przed Prorokiem ﷺ."),
        "dua_zawal_nimah" to DuaText("Schronienie przed utratą błogosławieństw", "O Allahu, szukam u Ciebie schronienia przed utratą Twoich błogosławieństw, przed zmianą dobrostanu, którym obdarzyłeś, przed Twoją nagłą karą i przed całym Twoim niezadowoleniem.", "Schronij się przed utratą błogosławieństw i nagłym nieszczęściem.", "Dua Proroka ﷺ."),
        "dua_useless_knowledge" to DuaText("Schronienie przed niekorzystną wiedzą", "O Allahu, szukam schronienia u Ciebie przed wiedzą, która nie przynosi pożytku, przed sercem, które się nie boi, przed duszą, która nigdy nie jest usatysfakcjonowana i przed duą, na którą nie ma odpowiedzi.", "Schronijcie się przed bezużyteczną wiedzą i sercem bez bojaźni Allaha.", "Dua schronienia przed Prorokiem ﷺ."),
        "dua_beneficial_knowledge" to DuaText("Przydatna wiedza i Halal Rizq", "O Allahu, proszę Cię o pożyteczną wiedzę, czyste zaopatrzenie i akceptowane czyny.", "Po modlitwie Fajr.", "Prorok ﷺ powiedział to po salam Fajr."),
        "dua_leprosy_diseases" to DuaText("Schronienie przed poważnymi chorobami", "O Allahu, szukam schronienia u Ciebie przed bielactwem nabytym, szaleństwem, trądem i wszelkimi złymi chorobami.", "Ochrona przed poważnymi chorobami.", "Sunna dua dla zachowania zdrowia."),
        "dua_fear_people" to DuaText("Strach przed wrogami lub prześladowcami", "O Allahu, stawiamy Cię przed nimi i szukamy u Ciebie schronienia przed ich złem.", "Kiedy obawiasz się wyrządzenia krzywdy ludziom lub osobie.", "Prorok ﷺ powiedział to, kiedy bał się ludzi."),
        "dua_shirk_protection" to DuaText("Ochrona przed ukrytym uchylaniem się", "O Allahu, szukam u Ciebie schronienia, abym świadomie nie łączył z Tobą czegokolwiek i proszę Cię o przebaczenie za to, co robię nieświadomie.", "Aby uchronić się przed popisywaniem się i ukrywaniem uchylania się.", "Ukryty uchylanie się jest bardziej ukryty niż pełzanie mrówki."),
        "dua_rain" to DuaText("Kiedy pada deszcz", "O Allahu, (ześlij) korzystny deszcz.", "Kiedy pada deszcz.", "Deszcz to czas, kiedy duas są akceptowane."),
        "dua_after_rain" to DuaText("Po deszczu", "Deszcz otrzymaliśmy dzięki hojności Allaha i Jego miłosierdziu.", "Po deszczu.", "Ten, kto tak mówi, jest wierzącym w Allaha."),
        "dua_istisqa" to DuaText("Prosząc o deszcz (Istisqa)", "O Allah, ześlij nam deszcz (trzy razy).", "Kiedy nie ma deszczu.", "Prorok ﷺ uczynił to dua w piątkowym kazaniu i padało."),
        "dua_heavy_rain" to DuaText("Nadmierny deszcz", "O Allahu (niech spadnie) wokół nas, a nie na nas.", "Kiedy jest za dużo deszczu.", "Chmury rozeszły się poprzez duet Proroka ﷺ."),
        "dua_wind" to DuaText("Kiedy wieje wiatr", "O Allah, proszę Cię o jego dobro, dobro w nim i dobro tego, z czym został wysłany, i szukam u Ciebie schronienia przed jego złem, złem w nim i złem tego, z czym został wysłany.", "Kiedy wieje silny wiatr lub burza.", "Prorok ﷺ stworzył ten dua podczas burz."),
        "dua_thunder" to DuaText("Słyszę grzmot", "Chwała Temu, którego grzmot wysławia swoją chwałą, a aniołowie ze strachu przed Nim.", "O usłyszeniu grzmotu — praktyka Abdullaha ibn az-Zubayra (RA).", "Zaczerpnięte z Sury ar-Ra'd (13:13)."),
        "dua_new_moon" to DuaText("Widzenie Księżyca w nowiu", "O Allahu, niech ten księżyc wzejdzie nad nami z błogosławieństwem, wiarą, bezpieczeństwem i islamem. (O księżycu) moim Panem i waszym Panem jest Allah.", "Po zobaczeniu nowiu księżyca.", "Sunna dua na każdy nowy miesiąc."),
        "dua_janaza_adult" to DuaText("Modlitwa Janaza (dorośli)", "O Allahu, przebacz naszym żywym i naszym zmarłym, obecnym i nieobecnym, naszym młodym i naszym starym, naszym mężczyznom i naszym kobietom. O Allahu, kogokolwiek z nas utrzymujesz przy życiu, utrzymuj go przy życiu w oparciu o islam, a kogokolwiek z nas powodujesz śmierć, spraw, aby umarł przez wiarę.", "Po trzecim takbiru modlitwy pogrzebowej.", "Dua Sunny dla zmarłej osoby dorosłej."),
        "dua_janaza_child" to DuaText("Modlitwa Janaza (dziecko)", "O Allahu, uczyń go dla nas poprzednikiem (i gospodarzem), uczyń go dla nas nagrodą i skarbem, i uczyń go orędownikiem za nas, którego wstawiennictwo zostanie przyjęte.", "W modlitwie pogrzebowej dziecka (w przypadku dziewczynki powiedz „ij'alhā”).", "Dua Sunny praktykowana przez Hanafich."),
        "dua_mayyit_awf" to DuaText("Szczegółowa Dua za zmarłego", "O Allahu, przebacz mu, zmiłuj się nad nim, obdarz go dobrobytem i przebacz mu. Spraw, aby jego przyjęcie było godne, a jego grób przestronny, obmyj go wodą, śniegiem i gradem i oczyść go z grzechów, tak jak białą szatę oczyszcza się z brudu.", "W modlitwie pogrzebowej lub za zmarłego.", "Awf ibn Malik (RA) żałował, że nie jest tą zmarłą osobą."),
        "dua_visiting_graves" to DuaText("Odwiedzanie grobów", "Pokój wam, wierzący i muzułmanie mieszkańcy tych domów. My także, jeśli Allah pozwoli, dołączymy do was. Proszę Allaha o pomyślność dla nas i dla Was.", "Przy wejściu na cmentarz.", "Odwiedzanie grobów przypomina o śmierci i życiu ostatecznym."),
        "dua_closing_eyes" to DuaText("Po zamknięciu oczu zmarłego", "O Allah, przebacz (imię), podnieś jego rangę wśród przewodników, bądź jego następcą wśród tych, których pozostawił. Przebacz nam i jemu, Panie światów; powiększ jego grób i napełnij go światłem.", "Przy zamykaniu oczu zmarłego (wspominanie jego imienia).", "Prorok ﷺ stworzył ten duet dla Abu Salamaha (RA)."),
        "dua_condolence" to DuaText("Kondolencje (Ta'ziyah)", "Zaprawdę, do Boga należy to, co wziął, i do Niego należy to, co dał. Wszystko u Niego ma wyznaczony termin. Bądźcie zatem cierpliwi i miejcie nadzieję na nagrodę.", "Składamy kondolencje rodzinie po śmierci.", "Prorok ﷺ wysłał tę wiadomość do swojej córki."),
        "dua_placing_in_grave" to DuaText("Złożenie zmarłego w grobie", "W imię Allaha i na drodze Wysłannika Allaha ﷺ.", "Podczas opuszczania zmarłego do grobu.", "Sunna dua pochówku."),
        "dua_sneezing" to DuaText("Kichanie", "Wszelka chwała jest dla Allaha. — Niech Allah zlituje się nad tobą. — Niech Allah cię prowadzi i uporządkuje twoje sprawy.", "Podczas kichania; słuchacz mówi „Yarhamukallah”, po czym ten, który kichnął, odpowiada.", "Jest to jedno z praw muzułmanina względem innego muzułmanina."),
        "dua_toilet_enter" to DuaText("Wejście do toalety", "W imię Allaha. O Allahu, szukam schronienia u Ciebie przed nieczystymi dżinami płci męskiej i żeńskiej.", "Przed wejściem do toalety lewą nogą.", "Bismillah staje się ekranem pomiędzy dżinem a osobą."),
        "dua_toilet_exit" to DuaText("Wyjście z toalety", "(O Allahu) Szukam Twojego przebaczenia.", "Podczas wychodzenia z toalety prawą nogą.", "Prorok ﷺ powiedział to po wyjściu z toalety."),
        "dua_thanking" to DuaText("Dziękować komuś", "Niech Allah wynagrodzi cię dobrem.", "Kiedy ktoś wyświadczy ci przysługę.", "Ktokolwiek to mówi, w pełni wyraził swoją wdzięczność."),
        "dua_love_for_allah" to DuaText("Kiedy ktoś mówi: „Kocham cię ze względu na Allaha”", "Niech On (Allah), ze względu na którego mnie kochasz, kocha ciebie.", "Kiedy ktoś mówi: „Kocham cię przez wzgląd na Allaha”.", "Sunna odpowiada na miłość ze względu na Allaha."),
        "dua_seeing_muslim_smile" to DuaText("Powitanie (Salaam)", "Pokój wam i miłosierdzie Allaha i Jego błogosławieństwa.", "Podczas spotkania z muzułmaninem.", "Wypowiedzenie pełnego salamu skutkuje trzydziestoma dobrymi uczynkami."),
        "dua_dressing" to DuaText("Ubieranie się", "Wszelka chwała należy się Allahowi, który mnie w to ubrał i zapewnił mi to bez żadnej mocy ani mocy z mojej strony.", "Kiedy się ubierasz.", "Radosna wieść o odpuszczeniu przeszłych grzechów."),
    )
}
